/**
 * Inlined icon bodies, keyed by Iconify name.
 *
 * astro-icon 0.8 resolves names over the network at build time through
 * api.astroicon.dev, whose snapshot is years old: eleven of the marks this
 * site uses 404 there and fail the build, including every AI-engineering mark.
 * Baking the bodies into the repo removes the remote dependency entirely, so a
 * build is reproducible offline and cannot break when an upstream set moves.
 *
 * Generated from the live Iconify API. Every name used anywhere on the site
 * must have an entry here; add the name and regenerate rather than reaching
 * for <Icon> again.
 */

export interface IconBody {
  /** Raw SVG children. Render with set:html inside an <svg>. */
  body: string;
  /** The viewBox the body was authored against. Sets differ; do not assume 24. */
  viewBox: string;
}

